16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Map;
19	
20	/**
21	 * Normalizes telephone numbers into <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
22	 * form. Spaces, dashes and brackets are stripped. A number that already carries a leading
23	 * {@code '+'} keeps its explicit country code; otherwise the Australian country code
24	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
25	 * digits. The result must contain between 8 and 15 digits after the {@code '+'}, matching
26	 * the E.164 length rule.
27	 *
28	 * <p>In addition to the overall length rule, the national number (the digits after the
29	 * country code) must have the exact length that country expects: {@code '+61'} (Australia)
30	 * requires 9 national digits and {@code '+1'} (NANP) requires 10. A number carrying one of
31	 * these country codes with the wrong national-number length cannot form valid E.164 and is
32	 * rejected.
33	 *
34	 * <p>The same logic backs both the request-time validator (so a number that cannot form
35	 * valid E.164 is rejected with HTTP 400) and the normalization applied before an
36	 * {@code Owner} is persisted, so the value a client is told about matches the value that
37	 * gets stored and compared for duplicates.
38	 */
39	public final class E164Telephone {
40	
41	    /**
42	     * Country calling code to the exact number of national digits it requires. Order is
43	     * irrelevant: when a number's digits could match more than one code, the longest
44	     * matching code is selected (see {@link #toE164(String)}), so entries may be listed
45	     * in any order.
46	     */
47	    private static final Map<String, Integer> NATIONAL_LENGTH = Map.of(
48	            "61", 9,
49	            "1", 10);
50	
51	    private E164Telephone() {
52	    }
53	
54	    /**
55	     * Convert a raw telephone number to E.164 form, or return {@code null} if it cannot
